"""Render the report-driven revision evidence beside the historical lab results."""
import html,json,os
import numpy as np
from pipeline.common import ROOT
from .common import path

def append(page,doc):
 fixes=json.loads((path('reports')/'research_report_fixes.json').read_text());ready=json.loads((path('reports')/'scientific_readiness.json').read_text());unc=json.loads((path('reports')/'joint_uncertainty.json').read_text());stress=json.loads((path('reports')/'kinematics_residual.json').read_text());geometry=fixes['geometry']['validation'];temporal=fixes['residual_validation'];esc=html.escape
 geometry_rows=''.join(f'<tr><td>{esc(name)}</td><td>{r["fits"]}</td><td>{r["accepted"]}</td><td>{r["joint_topology_valid_fraction"]:.4f}</td><td>{r["iou_all"]["mean"]:.4f}</td></tr>' for name,r in geometry.items());temporal_rows=''.join(f'<tr><td>{esc(name)}</td><td>{r["coarse"]:.5f}</td><td>{r["residual"]:.5f}</td><td>{100*(1-r["residual"]/r["coarse"]):.1f}%</td></tr>' for name,r in temporal.items());unc_rows=''.join(f'<tr><td>{esc(name)}</td><td>{r["nees"]["mean"]:.3f}</td><td>{r["joint_coverage_0.95"]["mean"]:.3f}</td><td>{r["marginal_coverage_0.95"]["mean"]:.3f}</td><td>{r["nll"]["mean"]:.3f}</td></tr>' for name,r in unc['metrics']['validation'].items());gates=''.join(f'<tr><td>{esc(name)}</td><td>{esc(r["status"])}</td><td>{esc(r["required"])}</td></tr>' for name,r in ready['gates'].items())
 rows=[r for r in stress['summary'] if r['split']=='synthetic_validation'];stress_rows=''.join(f'<tr><td>{r["hop_seconds"]}</td><td>{esc(r["method"])}</td><td>{r["position_rmse_px"]:.2f}</td><td>{r["velocity_rmse_px_s"]:.2f}</td><td>{r["event_recall"]:.3f}</td><td>{r["false_alarm_fraction"]:.3f}</td></tr>' for r in rows if r['method'] in ['v2','causal_residual','constant_velocity','half_second_linear_tail'])
 section='''<h2>Research-report fixes</h2><p>These updates implement the actionable review findings in parallel development candidates. No scientific freeze, baseline replacement or Track 2 action is authorized.</p><img src="review_fixes.png" alt="Joint topology checks, causal holdout reconstruction, joint coverage and synthetic motion trade-offs"><h3>Joint topology and reconstruction on the same validation probes</h3><table><tr><th>Variant</th><th>Probes</th><th>Joint-guard accepted</th><th>Joint validity</th><th>Mean IoU</th></tr>'''+geometry_rows+'''</table><p>Hole containment, hierarchy, orientation and boundary separation are checked at 69 times and 2,048 samples per loop after float32 serialization. Boundary clearance tolerance is 1e-9 times the larger loop extent (minimum unit extent). Coefficients retain their historical parameter order; decoded hole traversal is reversed. This is exact polygonal testing at the declared resolution, not a continuous-spline proof. Both rows use the same probe cohort; accepted counts refer to the final joint guard.</p><h3>Fixed coarse cubic plus bounded position residual</h3><table><tr><th>Holdout</th><th>Coarse NRMSE</th><th>Residual NRMSE</th><th>Reduction</th></tr>'''+temporal_rows+'''</table><p>Two/three compact spline atoms are projected orthogonally to the weighted coarse basis. Three residual coefficients won selection on five training participants only. The coarse state remains fixed, future observations are excluded and shape channels receive no residual. The 336 serialized pilot states are not a full-timeline ingestion store.</p><h3>Conditional joint covariance and position calibration</h3><table><tr><th>Variant</th><th>Mean 2D NEES</th><th>95% joint coverage</th><th>95% marginal coverage</th><th>NLL</th></tr>'''+unc_rows+'''</table><p>The 24-member conditional perturbation ensemble retains coarse/residual and x/y/velocity cross terms. The heteroscedastic block adds an empirical PSD representation-discrepancy allowance trained on held-out training positions. Only source-annotation 2D positions support calibration here. Velocity, physical motion and compound geometry remain uncalibrated; correlated probes do not certify a chi-square consistency test. Confidence intervals resample participant/video means; two validation participants provide limited independence.</p><h3>Causal residual stress test</h3><table><tr><th>Hop</th><th>Variant</th><th>Position RMSE px</th><th>Velocity RMSE px/s</th><th>Event recall</th><th>Quiet FAR</th></tr>'''+stress_rows+'''</table><p>Exact synthetic references do not replace real independent annotations. The residual helps held-out source reconstruction but does not beat constant velocity across these motion metrics. It is not promoted, and adaptive hopping remains deferred until the residual demonstrates a reliable advantage.</p><h3>Scientific gate ledger</h3><table><tr><th>Family</th><th>Status</th><th>Required evidence</th></tr>'''+gates+'''</table><p><a href="scientific_readiness.json">Machine-readable gate ledger and source/environment hashes</a> · <a href="research_report_fixes.json">Revision evidence</a> · <a href="joint_uncertainty.json">Uncertainty details and participant confidence intervals</a> · <a href="independent_reference_queue.csv">210 independent-review proposals</a> · <a href="independent_reference_contract.json">Annotation contract</a></p><p>Proposed contact-weighted fitting and star-convex fallback remain unpromoted experiments; this revision fixes hard topology first. Independent identity/contact/event labels, a fresh locked evaluation, full-timeline ring continuity and a clean rebuild remain open.</p>'''
 page=page.replace('<h2>Research-report fixes</h2>','<h2>Previous report revisions</h2>') if '<h2>Research-report fixes</h2>' in page else page
 page=page.replace('<h2>Spatial architecture:',section+'<h2>Spatial architecture:',1)
 doc+='\n## Research-report revision\n\n'+f"The report-driven changes live in parallel working candidates. Joint topology validity on 243 validation probes changes from {geometry['loop_guard']['joint_topology_valid_fraction']:.4f} to {geometry['joint_guard']['joint_topology_valid_fraction']:.4f}; mean IoU changes from {geometry['loop_guard']['iou_all']['mean']:.4f} to {geometry['joint_guard']['iou_all']['mean']:.4f}. Strict containment, orientation, boundary separation and float32 output are checked at 69 times / 2,048 samples. This remains sampled polygonal validity.\n\n"+'The fixed coarse cubic now has a causal, energy-bounded position residual with weighted orthogonality. Train-only selection chose three atoms. Holdout position NRMSE reductions are '+', '.join(f"{name}: {100*(1-r['residual']/r['coarse']):.1f}%" for name,r in temporal.items())+'. The real-source holdouts and synthetic motion tests are separate evidence. The residual is not promoted: it remains worse than constant velocity on important synthetic error/false-alarm metrics. No adaptive-hop promotion was made.\n\n'+'`derived/track1_lab/compound32_topology` contains accepted/rejected geometry states, hierarchy, orientation and tri-state quality flags. `derived/track1_lab/causal_residual` contains 336 pilot coarse/residual states. `derived/track1_lab/joint_kinematics` retains uncalibrated joint endpoint and augmented-coefficient covariance, including cross terms. Train-derived scalar and heteroscedastic representation-discrepancy position calibration are compared explicitly; they do not certify velocity or compound geometry uncertainty.\n\n'+'Use `python3 -m track1_lab.run --stage review-fixes`, then `--stage residual-stress`, `--stage scientific-audit` and `--stage report` with the same local runtime prefix. The CLI fixes the Python hash seed, seeds random/NumPy/Torch and requests strict deterministic Torch algorithms. Process pools seed workers. Resource logs distinguish the 16 GiB steady target, 18 GiB warning and 20 GiB hard stop.\n\n'+'The [scientific gate ledger](reports/track1_lab/scientific_readiness.json) prevents unknown evidence from becoming accepted validity. The new candidate reader exposes `FunctionalEntityState` without a hard-coded geometry control count, retains at most two mmap shards, and exposes unavailable covariance/appearance as `None`. It does not certify ingestion readiness. The [210-proposal annotation queue](reports/track1_lab/independent_reference_queue.csv) has no completed independent labels. Local-polynomial and regularized-spline derivative helpers are available for future reviewed trajectories; neither helper creates independent truth.\n\n'+'The report recommends further contact-weighted and star-convex ablations, independent references and a fresh participant holdout. Those proposals are not authorization to freeze or start Track 2, and they are not claimed completed by this revision. Frozen v1/v2 remain protected.\n'
 page=page.replace('<h3>Scientific gate ledger</h3>','<p><a href="evaluation_strata.json">Evaluation strata</a> report entity type, train-derived area quartiles, annotation provenance and ring count. Contact, occlusion and independent motion labels remain unknown.</p><h3>Scientific gate ledger</h3>')
 plot(fixes,unc,stress);return page,doc

def plot(fixes,unc,stress):
 os.environ['MPLCONFIGDIR']=str(ROOT/'work/mplconfig');import matplotlib
 matplotlib.use('Agg');import matplotlib.pyplot as plt
 fig,axes=plt.subplots(2,2,figsize=(14,10),constrained_layout=True);geometry=fixes['geometry']['validation'];names=list(geometry);axes[0,0].bar(names,[r['joint_topology_valid_fraction'] for r in geometry.values()]);axes[0,0].set(ylim=(.9,1.01),ylabel='Joint valid fraction',title='Same 243 validation window/protocol probes')
 temp=fixes['residual_validation'];x=np.arange(len(temp))
 for delta,name in [(-.18,'coarse'),(.18,'residual')]:axes[0,1].bar(x+delta,[r[name] for r in temp.values()],width=.36,label=name)
 axes[0,1].set(xticks=x,xticklabels=list(temp),ylabel='Normalized position RMSE',title='Train-selected bounded causal residual');axes[0,1].legend()
 for name,r in unc['metrics']['validation'].items():axes[1,0].plot([.5,.8,.9,.95],[r[f'joint_coverage_{p}']['mean'] for p in [.5,.8,.9,.95]],'o-',label=name)
 axes[1,0].plot([.5,1],[.5,1],'k--');axes[1,0].set(xlabel='Nominal joint ellipse coverage',ylabel='Observed source-position coverage',title='2D source-position only; two validation participants');axes[1,0].legend(fontsize=8)
 for r in stress['summary']:
  if r['split']=='synthetic_validation' and r['hop_seconds']==.125 and r['method'] in ['v2','causal_residual','constant_velocity','half_second_linear_tail']:
   offsets={'constant_velocity':(8,-18),'half_second_linear_tail':(8,10),'causal_residual':(5,-12),'v2':(-15,8)};axes[1,1].scatter(r['false_alarm_fraction'],r['velocity_rmse_px_s']);axes[1,1].annotate(r['method'],(r['false_alarm_fraction'],r['velocity_rmse_px_s']),xytext=offsets[r['method']],textcoords='offset points',fontsize=8)
 axes[1,1].margins(y=.15);axes[1,1].set(xlabel='Quiet false-alarm fraction',ylabel='Velocity RMSE native px/s',title='Synthetic cached states at 0.125 s hop; lower is better');fig.suptitle('Report-driven Track 1 fixes — open development evidence');fig.savefig(path('reports')/'review_fixes.png',dpi=140);plt.close(fig)

def append_hybrid(page,doc):
 architecture=json.loads((path('reports')/'hybrid_architecture.json').read_text());evaluation=json.loads((path('reports')/'hybrid_stream_evaluation.json').read_text());denominators=json.loads((path('reports')/'attempt_denominators.json').read_text())['summary'];metrics=evaluation['validation_metrics']['7'];attempted=sum(r['attempted'] for r in architecture['videos']);supported=sum(r['supported'] for r in architecture['videos']);esc=html.escape
 rows=''.join(f'<tr><td>{esc(name)}</td><td>{metrics[name]["0.0"]["velocity_rmse_native_px_s"]:.2f}</td><td>{metrics[name]["0.25"]["position_nrmse"]:.5f}</td><td>{metrics[name]["0.5"]["position_nrmse"]:.5f}</td></tr>' for name in ['causal_cv','causal_robust','constant_velocity','working_fixed'])
 counts=''.join(f'<tr><td>{part}</td><td>{r["proposed"]}</td><td>{r["source_support_eligible"]}</td><td>{r["emitted"]}</td><td>{r["missing_or_invalid"]}</td><td>{r["failure_fraction_all_proposed"]:.3f}</td></tr>' for part,r in denominators.items())
 section=f'''<h2>Option B: hybrid functional–kinematic state</h2><p>Functional history and instantaneous motion now have separate responsibilities. <code>functional_endpoint_state</code> and <code>functional_endpoint_velocity</code> describe the fitted history. <code>kinematics.position</code>, <code>kinematics.velocity</code> and the joint covariance come from past observations, independently of the cubic/residual derivative. Ambiguous legacy endpoint field names are removed from the development reader.</p><p>The separate stream records {attempted:,} attempted 4 Hz timestamps across seven videos; {supported:,} have recent-observation support. Unsupported records remain present. The primary estimator is local constant velocity; robust local linear fitting is retained as an alternative. Acceleration and independently calibrated velocity are unavailable. Residuals remain reconstruction features.</p><table><tr><th>Matched RGB-proxy comparison</th><th>Velocity RMSE px/s</th><th>250 ms position NRMSE</th><th>500 ms position NRMSE</th></tr>'''+rows+f'''</table><p>All rows use the same {evaluation['matched_supported_cutoffs']} supported cutoffs out of {evaluation['attempted_reference_cutoffs']} cached-reference cutoffs. Reference smoother: seven samples at 50 Hz; sensitivity remains recorded for five and eleven samples. No accepted fast-proxy validation reference is added. The CV continuation is a diagnostic baseline, not Track 2 training. A stronger average smoothed-velocity result for the polynomial does not make its extrapolation the authoritative motion state.</p><p>The combined geometry-pilot reader applies its original holdout exclusions before estimating kinematics. It never attaches the unrestricted full-stream state to a withheld-target probe. {evaluation['hidden_target_independence_checks']} perturbation checks verify hidden-target independence. All {evaluation['kinematic_states_checked']:,} stored kinematic records passed finite/covariance/causality checks. Covariance remains conditional and uncalibrated.</p><h3>Reconciled attempt denominators</h3><table><tr><th>Split</th><th>All proposed</th><th>Source timing supported</th><th>Emitted</th><th>Missing/invalid</th><th>Failure / all proposed</th></tr>'''+counts+'''</table><p>Source timing eligibility is evaluated before fitting. It is a selected-pilot audit, not independently preregistered dataset eligibility. Conditional geometry accuracy remains measured only on emitted states. Every no-target, sparse-input or candidate failure stays in the attempt ledger. The historical pre-reconciliation ledger is retained as evidence.</p><p><a href="hybrid_architecture.json">Architecture and stream manifests</a> · <a href="hybrid_stream_evaluation.json">Matched evaluation and checks</a> · <a href="attempt_denominators.json">Denominator definitions and counts</a> · <a href="compound32_attempts.parquet">Every proposed probe</a></p>'''
 page=page.replace('<h2>Research-report fixes</h2>',section+'<h2>Research-report fixes</h2>',1)
 doc+='\n## Option B: functional history plus causal kinematics\n\n'+f"The user selected the hybrid architecture. `derived/track1_lab/causal_kinematics` contains {attempted:,} attempted timestamps and {supported:,} recent-observation-supported states, including explicit failures. It uses 0.2 s local constant velocity and a separately retained robust alternative; neither comes from a polynomial derivative. Joint covariance is conditional, not independently calibrated.\n\n"+'`FunctionalEntityState.functional_endpoint_state` and `.functional_endpoint_velocity` are history diagnostics. `.kinematics.position`, `.velocity`, `.covariance` and `.support_valid` are the separate causal estimate. The development interface version is `track1-v3.0.0-dev.hybrid1`; removed ambiguous endpoint names intentionally fail instead of silently changing semantics. `CandidateStore` preserves the geometry pilot’s hidden-target exclusions. `KinematicStore` reads the full-stream data and must not be substituted into holdout evaluations. Both retain at most two video shards.\n\n'+f"The [matched RGB-proxy audit](reports/track1_lab/hybrid_stream_evaluation.json) covers {evaluation['matched_supported_cutoffs']} / {evaluation['attempted_reference_cutoffs']} original cutoffs and {evaluation['hidden_target_independence_checks']} hidden-target perturbation checks. It does not supply new independent fast-motion truth. Steady/abrupt/stationary acceptance thresholds must be preregistered after annotation reliability is understood; raw cubic forecast errors remain diagnostics rather than universal Track 1 gates.\n\n"+'The [reconciled probe ledger](reports/track1_lab/attempt_denominators.json) records 288 validation proposals, 283 source-timing-supported probes and 243 emitted compound states. All 45 non-emitted proposals remain counted. Source timing support is not independently certified eligibility. Conditional quality and attempted-state failure rates are reported separately.\n\n'+'Reproduce the new stages with `python3 -m track1_lab.run --stage hybrid`, then `--stage hybrid-evaluate`, `--stage scientific-audit` and `--stage report`, using the existing local runtime prefix. Full-timeline compound geometry and cross-window ring identity remain unfinished; this is not a complete default ingestion release. Track 2 remains on hold.\n'
 return page,doc

def append_remediation(page,doc):
 load=lambda name:json.loads((path('reports')/(name+'.json')).read_text());certificate=load('topology_certificate');detail=load('neutral_detail');store=load('neutral_detail_store');kalman=load('kalman_comparison');synthetic=load('kinematics_kalman');references=load('independent_reference_validation');esc=html.escape
 cr=''.join(f'<tr><td>{part}</td><td>{r["attempted"]}</td><td>{r["sampled_valid"]}</td><td>{r["certified"]}</td><td>{r["certified_and_epoch_valid"]}</td><td>{r["unresolved"]}</td><td>{r["known_epoch_crossing_probes"]}</td></tr>' for part,r in certificate['metrics'].items());dr=''.join(f'<tr><td>{name}</td><td>{r["coarse"]:.5f}</td><td>{r["detail"]:.5f}</td><td>{100*(1-r["detail"]/r["coarse"]):.1f}%</td></tr>' for name,r in detail['validation'].items());km=kalman['validation_metrics']['7'];kr=''.join(f'<tr><td>{name}</td><td>{km[name]["0.0"]["velocity_rmse_native_px_s"]:.2f}</td><td>{km[name]["0.25"]["position_nrmse"]:.5f}</td><td>{km[name]["0.5"]["position_nrmse"]:.5f}</td></tr>' for name in ['causal_cv','causal_robust','kalman_cv','kalman_cv_robust']);sr=''.join(f'<tr><td>{r["hop_seconds"]:.3f}</td><td>{r["method"]}</td><td>{r["position_rmse_px"]:.2f}</td><td>{r["velocity_rmse_px_s"]:.2f}</td><td>{r["event_recall"]:.3f}</td><td>{r["false_alarm_fraction"]:.3f}</td></tr>' for r in synthetic['summary'] if r['split']=='synthetic_validation' and r['method'] in ['constant_velocity','kalman_cv','kalman_cv_robust'])
 section='''<h2>Latest remediation: structural fixes, no scientific freeze</h2><img src="remediation.png" alt="Certificate outcomes, endpoint-neutral reconstruction and synthetic Kalman trade-offs"><h3>Continuous-curve certificates and source epochs</h3><table><tr><th>Split</th><th>Historical emitted</th><th>Sampled valid</th><th>Curve certified</th><th>Certified + stable epochs</th><th>Unresolved certificate</th><th>Known topology-change probes</th></tr>'''+cr+'''</table><p>The certificate uses outward-rounded Bernstein bounds, adaptive time subdivision, local injectivity and adjacent-piece tangent cones. It applies to <strong>canonical_tensor_bezier1</strong> in normalized shape coordinates at tolerance 1e-8. The decoder has identical shared endpoints, and the reader verifies coefficient, geometry-contract and decoder-source hashes. It does not transfer the certificate to an independently evaluated SciPy curve or a raster mask. Original sampled-mask IoU tables below remain historical measurements, not newly measured canonical-decoder scores.</p><p><code>normalized_geometry_curves(..., require_certificate=True)</code> rejects unresolved certificates, changed coefficients/decoder, and windows without a stable retained topology/correspondence epoch. Mathematical curve validity is separate from source completeness and identity. New fits reset their retained segment on known topology changes or ambiguous ring matching. The event ledger records annotation topology changes, not verified physical splits/merges.</p><p>Counts above are conditional on historically emitted states. The complete proposal denominators remain 720 training / 288 validation; source-timing-supported counts remain 704 / 283. A smaller certified subset does not establish 99% eligibility coverage.</p><h3>Endpoint-neutral history detail</h3><table><tr><th>Holdout</th><th>Coarse NRMSE</th><th>Neutral-detail NRMSE</th><th>Reduction</th></tr>'''+dr+f'''</table><p>The optional detail is q(t) times a compact spline basis, with q=(1-t)^2 and a weighted-null-space projection. Training-only selection chose three atoms. All {store['states']} serialized pilot states have exactly zero detail contribution to endpoint position and velocity; maximum serialized weighted orthogonality error is {store['max_serialized_weighted_orthogonality_error']:.3g}. Errors in this table are means of per-video RMSE and must not be numerically mixed with older pooled summaries. Six optional multi-scale change descriptors are stored with validity masks. Detail is reconstruction-only and is not substituted into the four-mode core or its GL4 collocation.</p><h3>Causal Kalman CV comparison</h3><table><tr><th>Variant</th><th>RGB-proxy velocity RMSE px/s</th><th>250 ms position NRMSE</th><th>500 ms position NRMSE</th></tr>'''+kr+f'''</table><p>Same {kalman['matched_cutoffs']} matched cached-reference cutoffs, seven-sample 50 Hz reference. Fixed process spectral density .01 in normalized coordinates; no validation parameter selection. Joseph covariance updates reject substantial PSD failures. The Kalman posterior is conditional and uncalibrated. Stronger smoothed-proxy scores do not prove fast-motion accuracy.</p><table><tr><th>Synthetic hop</th><th>Variant</th><th>Position RMSE px</th><th>Velocity RMSE px/s</th><th>Event recall</th><th>Quiet FAR</th></tr>'''+sr+'''</table><p>The exact synthetic stress test exposes the trade-off: the Kalman variants can lower false movement or velocity error while worsening cached position or event recall. Neither replaces CV as the default. No IMM/CA regime probabilities, independently calibrated velocity, or Track 2 model is claimed.</p><h3>Independent-reference ingestion</h3><p>'''+str(references['proposals'])+''' proposals were checked. Submitted files require scoped paths, matching hashes/reviewers, ordered native-pixel anchors, sampling/duration/visibility checks. Declared locked files are not opened by the development audit. There are no validated final independent references and no newly manufactured locked set. Public contact relations cannot substitute for contact-boundary geometry.</p><p><a href="topology_certificate.json">Certificate outcomes</a> · <a href="topology_certificate.parquet">Per-probe proof/failure ledger</a> · <a href="neutral_detail.json">History-detail results</a> · <a href="neutral_detail_store.json">Serialization checks</a> · <a href="kalman_comparison.json">Kalman audit</a> · <a href="kinematics_kalman.json">Exact-motion stress test</a> · <a href="independent_reference_validation.json">Reference checks and missing fields</a> · <a href="remediation_manifest.json">Source/evidence manifest</a></p>'''
 page=page.replace('<h2>Option B:',section+'<h2>Option B:',1)
 doc+='\n## Latest remediation report\n\n'+f"Continuous-curve certificates distinguish sampled validity from conservatively established validity of `canonical_tensor_bezier1`. Validation: {certificate['metrics']['validation']['certified']} / {certificate['metrics']['validation']['attempted']} curve-certified emitted probes; {certificate['metrics']['validation']['certified_and_epoch_valid']} also pass the retained source-epoch checks. These are not full-dataset coverage rates. All unresolved cases and annotation-mode changes remain recorded. The certificate is bound to coefficient bytes, ring contract and decoder source; it does not certify legacy SciPy/raster output or hidden source rings.\n\n"+'New compound fits retain only the latest stable source-topology/correspondence segment. Cached windows with known count changes or matching ambiguity are flagged; an annotation transition is not a verified physical split/merge. Persistent independent ring lineage remains unverified.\n\n'+'The optional endpoint-neutral detail uses a `(1-t)^2` envelope and a weighted null-space basis. Three atoms were selected using training participants only. All 336 serialized pilot states preserve endpoint position/velocity exactly, with float32 weighted orthogonality audited. Six multi-scale descriptors are optional history evidence; they are not authoritative motion or part of the core GL4 collocation.\n\n'+'Plain and robust-innovation Kalman CV models use CPU float64, Joseph updates and strict covariance validation. Existing RGB-proxy and exact synthetic results are retained separately. The synthetic event/position trade-off prevents default promotion; CV remains the primary causal baseline. No calibrated Kalman posterior, CA/IMM regime mixture or independent fast-motion improvement is claimed.\n\n'+'Independent-reference ingestion now validates reviewer/hash/path, sampling, visibility and native-pixel anchor contracts. Declared locked labels stay unopened in the development audit. All existing proposals still lack validated final references. Uncertainty components are bookkeeping with potentially overlapping errors, not an identified independent additive decomposition.\n\n'+'Reproduce with `--stage remediation`, `--stage remediation-audit`, `--stage kalman-stress`, `--stage scientific-audit` and `--stage report` through `python3 -m track1_lab.run`, using the existing runtime prefix. Evidence is in [the remediation manifest](reports/track1_lab/remediation_manifest.json). Contact-local fitting, independent contact/identity annotation, verified lineage, full calibrated uncertainty, a fresh locked participant audit and a clean full-timeline rebuild remain open. No finalization or Track 2 action was performed.\n'
 remediation_plot(certificate,detail,synthetic);return page,doc

def remediation_plot(certificate,detail,synthetic):
 os.environ['MPLCONFIGDIR']=str(ROOT/'work/mplconfig');import matplotlib
 matplotlib.use('Agg');import matplotlib.pyplot as plt
 fig,axes=plt.subplots(1,3,figsize=(17,5),constrained_layout=True);r=certificate['metrics']['validation'];axes[0].bar(['Sampled valid','Curve certified','Certificate + epochs'],[r['sampled_valid'],r['certified'],r['certified_and_epoch_valid']],color=['#586c85','#277fbd','#2d9c75']);axes[0].set(ylabel='Emitted validation probes',title='Same 243 historical emitted probes');axes[0].tick_params(axis='x',labelrotation=15)
 names=list(detail['validation']);x=np.arange(len(names))
 for dx,key in [(-.18,'coarse'),(.18,'detail')]:axes[1].bar(x+dx,[detail['validation'][name][key] for name in names],width=.36,label=key)
 axes[1].set(xticks=x,xticklabels=names,ylabel='Mean per-video position NRMSE',title='Reconstruction-only, endpoint-neutral');axes[1].legend()
 for r in synthetic['summary']:
  if r['split']=='synthetic_validation' and r['hop_seconds']==.125 and r['method'] in ['constant_velocity','kalman_cv','kalman_cv_robust']:
   marker='o' if r['event_recall']>=.8 else '^';axes[2].scatter(r['position_rmse_px'],r['velocity_rmse_px_s'],s=60+700*r['false_alarm_fraction'],marker=marker);axes[2].annotate(r['method'],(r['position_rmse_px'],r['velocity_rmse_px_s']),xytext=(-5,10),textcoords='offset points',fontsize=8,ha='right')
 axes[2].margins(.3);axes[2].set(xlabel='Synthetic cached position RMSE px',ylabel='Velocity RMSE px/s',title='125 ms hop; marker size = quiet FAR');fig.suptitle('Open remediation evidence — no default promotion or scientific freeze');fig.savefig(path('reports')/'remediation.png',dpi=140);plt.close(fig)
